import { Book } from "@/lib/types";

export const romans: Book = {
  id: "romans",
  name: "Römer",
  shortName: "Röm",
  testament: "new",
  introduction: `Die Gerechtigkeit, die vor Gott Bestand hat\nIm Winter 56/57 n.Chr. besuchte der Apostel Paulus das dritte Mal die Gemeinde in Korinth. Er wohnte bei Gajus, in dessen Haus auch die Gemeinde zusammenkam, und blieb etwa drei Monate in der Stadt. Weil er seine Missionsarbeit in den Städten der ägäischen Küste nun als abgeschlossen ansah, hielt er nach einem neuen Arbeitsfeld Ausschau. Das sah er in Spanien und hoffte für die Arbeit dort auf die Unterstützung der Gemeinde in Rom. Weil er vorher aber noch nie in dieser Gemeinde gewesen war, wollte er sich und seine Lehre ausführlich vorstellen. Das tat er in diesem Brief an die Christen in Rom, den er von Phöbe, einer Diakonin der Gemeinde Kenchreä, überbringen ließ. Er selbst wollte allerdings zunächst die Geldsammlung der Gemeinden Mazedoniens und Achajas nach Jerusalem bringen. Auf dem Weg nach Spanien wollte er dann in Rom vorbeikommen.\nAls **Paulus den Brief** schrieb, bestand die **Gemeinde in Rom** offenbar schon länger als zwei Jahrzehnte, so lange, wie er bekehrt war. Sie war ganz unabhängig von ihm gewachsen und hatte sich in verschiedenen Hauskreisen organisiert.\nDas Hauptthema des Römerbriefes könnte man so formulieren: Die Gerechtigkeit, die vor Gott Bestand hat. Paulus entfaltet diesen Gedanken in vier Hauptpunkten: die Gerechtigkeit, die vor dem Zorn Gottes rettet (1-5); die Gerechtigkeit, die das Leben des Christen regiert (5-8); die Gerechtigkeit, die für das Volk Israel gilt (9-11) und die Gerechtigkeit, die im Alltag des Christen sichtbar wird (12-15).\n****Wie ein Mensch durch den Glauben an Jesus Christus die Gerechtigkeit bekommen kann, mit der er vor dem Urteil des heiligen Gottes besteht.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Es schreibt Paulus, ein Sklave* von Jesus Christus, zum Apostel berufen und dazu bestimmt, Gottes gute Botschaft bekannt zu machen.", heading: "Paulus und sein Auftrag in Rom", footnotes: ["Ein Sklave (griech. doulos) ist ein Mensch, der rechtlich und wirtschaftlich Eigentum eines anderen Menschen ist. Christen verstanden sich als Sklaven von Jesus Christus, weil dieser sie aus der Sklaverei der Sünde \"freigekauft\" hatte, und betrachteten diesen Titel als Auszeichnung."] },
      { number: 2, text: "Dieses Evangelium hat Gott schon vor langer Zeit durch seine Propheten in heiligen Schriften angekündigt." },
      { number: 3, text: "Es ist die Botschaft von seinem Sohn, der als Mensch ein Nachkomme Davids ist" },
      { number: 4, text: "und sich durch die Auferstehung aus den Toten und in der Kraft des Heiligen Geistes als Sohn Gottes erwiesen hat: die Botschaft von Jesus Christus, unserem Herrn." },
      { number: 5, text: "Er hat uns in seiner Gnade zu Aposteln gemacht und uns beauftragt, Menschen aus allen Völkern zum Gehorsam des Glaubens zu führen, damit sein Name dadurch geehrt wird." },
      { number: 6, text: "Auch ihr gehört zu ihnen, denn auch ihr wurdet von Jesus Christus berufen." },
      { number: 7, text: "Mein Brief geht an euch, von Gott geliebte und berufene Heilige in Rom. Gnade und Frieden wünsche ich euch von Gott, unserem Vater, und von Jesus Christus, dem Herrn." },
      { number: 8, text: "Als Erstes danke ich meinem Gott durch Jesus Christus für euch alle, denn in der ganzen Welt spricht man von eurem Glauben." },
      { number: 9, text: "Gott, dem ich mit ganzem Herzen diene, indem ich das Evangelium seines Sohnes verkündige, ist mein Zeuge, dass ich euch ständig erwähne," },
      { number: 10, text: "wenn ich zu ihm bete. Und ich flehe ihn an, dass er es mir doch endlich ermöglicht, zu euch zu kommen, wenn das seinem Willen entspricht." },
      { number: 11, text: "Denn ich sehne mich sehr danach, euch persönlich kennenzulernen, damit ich euch etwas von dem weitergeben kann, was Gott mir geschenkt hat, und ihr gestärkt werdet –" },
      { number: 12, text: "besser gesagt, damit wir, wenn ich bei euch bin, durch unseren gemeinsamen Glauben gegenseitig ermutigt werden." },
      { number: 13, text: "Ihr sollt wissen, liebe Geschwister, dass ich es mir schon oft vorgenommen habe, zu euch zu kommen, damit ich wie bei den anderen Völkern auch unter euch einige Frucht ernten kann. Doch bis jetzt wurde ich daran gehindert." },
      { number: 14, text: "Denn ich fühle mich allen Menschen verpflichtet: solchen aus zivilisierten genauso wie solchen aus unzivilisierten Völkern, Gebildeten ebenso wie Ungebildeten." },
      { number: 15, text: "Darum möchte ich auch euch in Rom gern die gute Botschaft verkündigen." },
      { number: 16, text: "Denn ich bekenne mich offen und ohne Scham zu dieser Botschaft: Sie ist ja Gottes Kraft und rettet jeden, der ihr glaubt. Das gilt zunächst für Juden, aber auch für alle anderen Menschen.", heading: "1-5: Gerechtigkeit rettet vor Gottes Zorn\nGottes Botschaft bringt Rettung" },
      { number: 17, text: "Denn im Evangelium zeigt Gott uns seine Gerechtigkeit, eine Gerechtigkeit, die aus dem Vertrauen auf Gott kommt und zum Glauben hinführt, wie es in der Schrift steht: \"Der Gerechte wird leben, weil er glaubt.\" *", footnotes: ["Habakuk 2,4 sinngemäß nach der LXX zitiert."] },
      { number: 18, text: "Gott lässt nämlich seinen Zorn sichtbar werden. Vom Himmel her wird er über alle Gottlosigkeit und Ungerechtigkeit der Menschen hereinbrechen, die durch Unrecht die Wahrheit niederhalten.", heading: "Die Ungerechtigkeit der Menschen (1)" },
      { number: 19, text: "Denn was Menschen von Gott wissen können, ist ihnen bekannt, er selbst hat es ihnen vor Augen gestellt." },
      { number: 20, text: "Denn seine unsichtbare Wirklichkeit, seine ewige Macht und sein göttliches Wesen sind seit Erschaffung der Welt in seinen Werken zu erkennen. Die Menschen haben also keine Entschuldigung." },
      { number: 21, text: "Trotz allem, was sie von Gott wussten, ehrten sie ihn nicht als Gott und brachten ihm keinerlei Dank. Stattdessen verloren sich ihre Gedanken ins Nichts, und in ihren uneinsichtigen Herzen wurde es finster." },
      { number: 22, text: "Sie hielten sich für Weise und wurden zu Narren." },
      { number: 23, text: "Die Herrlichkeit des unvergänglichen Gottes vertauschten sie mit Bildern von sterblichen Menschen, mit Abbildern von Vögeln, vierfüßigen und kriechenden Tieren." },
      { number: 24, text: "Darum hat Gott sie den Begierden ihrer Herzen ausgeliefert; er hat sie ihrer Unsittlichkeit preisgegeben, so dass sie ihre eigenen Körper schändeten." },
      { number: 25, text: "Sie vertauschten die Wahrheit Gottes mit der Lüge. Sie beteten die Geschöpfe an und verehrten sie anstelle des Schöpfers, der doch für immer und ewig zu preisen ist. Amen*!", footnotes: ["Amen. Hebräisch: Es werde wahr! Oder: So sei es!"] },
      { number: 26, text: "Darum hat Gott sie entehrenden Leidenschaften ausgeliefert. Ihre Frauen vertauschten den natürlichen Geschlechtsverkehr mit dem widernatürlichen," },
      { number: 27, text: "und ihre Männer machten es genauso. Sie gaben den natürlichen Verkehr mit den Frauen auf und wurden von wildem Verlangen zueinander gepackt. Männer trieben es schamlos mit Männern. So empfingen sie den gebührenden Lohn für ihre Verirrung* an sich selbst.", footnotes: ["Verirrung. Gemeint ist offenbar die Verirrung ihrer Gottesverehrung, wie es der Zusammenhang nahe legt."] },
      { number: 28, text: "Und weil sie es nicht für gut hielten, Gott anzuerkennen, lieferte Gott sie einem verworfenen Denken aus, so dass sie tun, was man nicht tun darf." },
      { number: 29, text: "Jede Art von Unrecht, Bosheit, Habsucht und Gemeinheit ist bei ihnen zu finden. Sie sind voller Neid, Mord, Streit, List und Tücke." },
      { number: 30, text: "Sie reden gehässig über andere und verleumden sie. Sie hassen Gott, sind gewalttätig, hochmütig und prahlerisch. Im Bösen sind sie sehr erfinderisch, und ihre Eltern verachten sie." },
      { number: 31, text: "Sie sind unbelehrbar, unzuverlässig, gefühllos und kennen kein Erbarmen." },
      { number: 32, text: "Obwohl sie wissen, dass jeder, der so handelt, nach Gottes Gesetz den Tod verdient, tun sie es nicht nur selbst, sondern finden es auch noch gut, wenn andere es ebenso machen." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Deshalb bist du nicht zu entschuldigen, lieber Mensch, auch wenn du das alles verurteilst. Du sitzt zwar über einen anderen zu Gericht, doch verurteilst du dich damit selbst, denn du tust ja genau das, was du verurteilst.", heading: "Die Selbstgerechtigkeit der Juden (2)" },
      { number: 2, text: "Nun wissen wir natürlich, dass Gott die verurteilt, die so etwas tun, und dass sein Urteil absolut gerecht ist." },
      { number: 3, text: "Meinst du etwa, du könntest dem Gericht Gottes entgehen, wenn du die verurteilst, die so etwas tun, aber doch genau dasselbe machst?" },
      { number: 4, text: "Oder verachtest du nur seine große Güte, Nachsicht und Geduld? Begreifst du denn nicht, dass er dich mit seiner Güte zur Umkehr bringen will?" },
      { number: 5, text: "Doch du bist starrsinnig und nicht bereit, deine Einstellung zu ändern. So lädst du dir selbst den Zorn Gottes auf und vermehrst ihn noch, bis er schließlich am \"Tag des Zorns\" über dich hereinbricht, an dem Tag, an dem offenbar wird, dass Gottes Urteil gerecht ist." },
      { number: 6, text: "Gott wird jedem das geben, was er für sein Tun verdient hat." },
      { number: 7, text: "Den einen, die unermüdlich das Gute tun und alles dransetzen, um an Gottes Herrlichkeit, Ehre und Unvergänglichkeit teilzuhaben, gibt er das ewige Leben." },
      { number: 8, text: "Den anderen aber, die nur an sich selbst denken und sich weigern, der Wahrheit zu gehorchen, stattdessen aber dem Unrecht gehorsam sind, gilt sein grimmiger Zorn." },
      { number: 9, text: "Bedrängende Angst wird über die Menschen kommen, die Böses tun. Das gilt zuerst für Juden, aber auch für alle anderen Menschen." },
      { number: 10, text: "Ewige Herrlichkeit jedoch und Ehre und Frieden werden die erhalten, die Gutes tun. Auch das gilt zuerst für Juden, dann aber auch für alle anderen Menschen." },
      { number: 11, text: "Denn bei Gott gibt es keinerlei Bevorzugung." },
      { number: 12, text: "Alle Menschen, die sündigen und keine Beziehung zum Gesetz Gottes haben, werden auch ohne Gesetz ins Verderben gehen. Und alle, die trotz des Gesetzes sündigen, werden durch dieses Gesetz verurteilt werden." },
      { number: 13, text: "Denn nicht die, die hören, was das Gesetz sagt, werden von Gott für unschuldig erklärt, sondern die, die tun, was es verlangt." },
      { number: 14, text: "Und wenn nun Menschen aus nichtjüdischen Völkern, die keine Beziehung zum Gesetz Gottes haben, von sich aus so handeln, wie es das Gesetz fordert, dann tragen sie das Gesetz in sich." },
      { number: 15, text: "Sie beweisen damit, dass ihnen die Forderungen des Gesetzes ins Herz geschrieben sind. Das zeigt sich auch an der Stimme ihres Gewissens und am Widerstreit ihrer Gedanken, die sich gegenseitig anklagen oder auch entschuldigen." },
      { number: 16, text: "Der Tag des Gerichts wird das ans Licht bringen, der Tag, an dem Gott durch Jesus Christus die verborgensten Dinge der Menschen richten wird. So entspricht es der guten Botschaft, die mir anvertraut ist." },
      { number: 17, text: "Nun zu dir: Du kannst von dir sagen, ein Jude zu sein, und fühlst dich sicher, weil du das Gesetz hast. Du bist stolz auf deine Beziehung zu Gott." },
      { number: 18, text: "Aus dem Gesetz kennst du seinen Willen und kannst beurteilen, worauf es ankommt." },
      { number: 19, text: "Du traust dir zu, die Blinden zu führen und denen im Dunkeln das Licht zu bringen;" },
      { number: 20, text: "du willst ein Erzieher für die Unverständigen und ein Lehrer für die Unwissenden sein, weil du das Gesetz Gottes hast, den Inbegriff von Erkenntnis und Wahrheit." },
      { number: 21, text: "Du belehrst andere, warum nicht auch dich selbst? Du predigst, man dürfe nicht stehlen – und warum stiehlst du?" },
      { number: 22, text: "Du sagst, man soll die Ehe nicht brechen – warum brichst du sie? Du verabscheust die Götzen – und warum bereicherst du dich dann an ihren Tempeln?" },
      { number: 23, text: "Du bist stolz auf das Gesetz – und warum brichst du es selbst und machst Gott Schande damit?" },
      { number: 24, text: "So steht es schon in der Schrift: \"Euretwegen wird der Name Gottes bei den Völkern verlästert.\" *", footnotes: ["Jesaja 52,5 nach der LXX zitiert; siehe auch Hesekiel 36,20-23."] },
      { number: 25, text: "Auch die Beschneidung nützt dir nur dann etwas, wenn du das Gesetz befolgst. Übertrittst du das Gesetz, bist du praktisch ein Unbeschnittener* geworden.", footnotes: ["Unbeschnittener. Ausdruck für einen Menschen, der nicht zum Bund Gottes gehört. Siehe 1. Mose 17,9-14."] },
      { number: 26, text: "Und wenn ein Unbeschnittener die Forderungen des Gesetzes erfüllt, gilt er vor Gott dann etwa nicht als Beschnittener?" },
      { number: 27, text: "So wird der Unbeschnittene, der das Gesetz gehalten hat, über dich das Urteil sprechen, der das Gesetz zwar buchstabengenau kennt und auch beschnitten ist, es aber doch übertreten hat." },
      { number: 28, text: "Nicht der ist nämlich ein Jude, der es nach außen hin ist, und nicht der körperliche Vollzug ist die wirkliche Beschneidung." },
      { number: 29, text: "Ein wahrer Jude ist der, der es innerlich ist, und die wahre Beschneidung ist die, die am Herzen geschieht. Sie kommt nicht durch die genaue Befolgung der Vorschrift zustande, sondern durch den Geist Gottes. Ein solcher Jude sucht nicht den Beifall von Menschen. Sein Lob kommt von Gott." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Aber was für einen Vorteil haben dann die Juden noch, und was nützt dann noch die Beschneidung?", heading: "Die Gerechtigkeit durch Glauben (3-4)\nDie Gerechtigkeit Gottes" },
      { number: 2, text: "Nun, die Juden haben den anderen Völkern in jeder Hinsicht viel voraus, vor allem, dass Gott ihnen seine Worte anvertraut hat." },
      { number: 3, text: "Es stimmt zwar, dass einige dieses Vertrauen enttäuscht haben. Aber kann ihr Unglaube etwa die Treue Gottes aufheben?" },
      { number: 4, text: "Auf keinen Fall! Vielmehr sollte dadurch klar werden, dass Gott zuverlässig und wahrhaftig ist, jeder Mensch aber letztlich ein Lügner, so wie es in der Schrift heißt: \"Du sollst Recht behalten mit deinen Worten, sie werden sich als zuverlässig erweisen, und du wirst dich siegreich behaupten, wenn man dich zur Rechenschaft ziehen will.\" *", footnotes: ["Psalm 51,6"] },
      { number: 5, text: "Wenn aber unsere Ungerechtigkeit Gottes Gerechtigkeit erst richtig zur Geltung bringt, was sagen wir dann? Ist Gott vielleicht ungerecht, wenn er seinen Zorn über uns kommen lässt? – Ich frage sehr menschlich. –" },
      { number: 6, text: "Auf keinen Fall! Denn wie könnte Gott sonst die Welt richten?" },
      { number: 7, text: "Wenn nun aber die Wahrheit Gottes erst dadurch richtig zur Geltung kommt, dass ich ein Lügner bin, und sein Ruhm erst dadurch richtig groß wird, warum werde ich dann noch als Sünder gerichtet?" },
      { number: 8, text: "Könnten wir dann nicht gleich sagen: \"Tun wir doch das Böse, damit Gutes dabei herauskommt!\"? Einige verleumden uns ja und behaupten, das sei es, was wir lehren. Gottes Gericht wird sie zu Recht treffen." },
      { number: 9, text: "Aber wie ist es nun? Machen wir etwa Ausflüchte? Ganz und gar nicht. Wir haben ja schon den Beweis erbracht, dass die Juden genauso wie die anderen Völker in der Gewalt der Sünde sind." },
      { number: 10, text: "So steht es in der Schrift: \"Keiner ist gerecht, auch nicht einer." },
      { number: 11, text: "Keiner hat Einsicht und fragt nach Gott." },
      { number: 12, text: "Alle haben sie den rechten Weg verlassen und sind unbrauchbar geworden. Niemand ist da, der Gutes tut, kein Einziger.\"*", footnotes: ["Psalm 14,1-3; 53,4."] },
      { number: 13, text: "\"Ihre Kehle ist ein offenes Grab und mit ihrer Zunge formen sie Lügen.\"* \"Schlangengift verbirgt sich hinter ihren Lippen.\"*", footnotes: ["Psalm 5,10", "Psalm 140,4"] },
      { number: 14, text: "\"Ihr Mund ist voller Flüche und Drohungen.\"*", footnotes: ["Psalm 10,7"] },
      { number: 15, text: "\"Ihre Füße sind schnell, wenn es darum geht, Blut zu vergießen." },
      { number: 16, text: "Sie hinterlassen Verwüstung und Elend," },
      { number: 17, text: "und was zum Frieden führt, kennen sie nicht.\"*", footnotes: ["Jesaja 59,7-8"] },
      { number: 18, text: "\"Von Gottesfurcht wissen sie nichts.\"*", footnotes: ["Psalm 36,2"] },
      { number: 19, text: "Das sagt das Gesetz, und wir wissen: Alles, was es sagt, richtet sich an die, denen es verordnet wurde. So wird jeder Mund gestopft und die ganze Welt sieht sich dem Urteil Gottes verfallen." },
      { number: 20, text: "Denn durch das Halten von Geboten wird kein Mensch vor Gott gerecht. Das Gesetz führt nur dazu, dass man seine Sünde erkennt." },
      { number: 21, text: "Doch jetzt ist die Gerechtigkeit Gottes sichtbar geworden, und zwar unabhängig vom Gesetz, aber in Übereinstimmung mit dem Gesetz und den Worten der Propheten.", heading: "Gerecht werden durch Glauben" },
      { number: 22, text: "Es ist die Gerechtigkeit Gottes, die durch den Glauben an Jesus Christus geschenkt wird und allen zugutekommt, die glauben. Da ist kein Unterschied zwischen Jude und Nichtjude," },
      { number: 23, text: "denn alle haben gesündigt und die Herrlichkeit Gottes* verloren.", footnotes: ["Herrlichkeit Gottes. Damit ist wohl die ursprüngliche Herrlichkeit gemeint, die der Mensch als Ebenbild Gottes hatte."] },
      { number: 24, text: "Doch werden sie allein durch seine Gnade ohne eigene Leistung gerecht gesprochen, und zwar aufgrund der Erlösung, die durch Jesus Christus geschehen ist." },
      { number: 25, text: "Ihn hat Gott zu einer Stätte für Sühne gemacht. Durch sein vergossenes Blut ist die Sühne vollzogen worden, und durch den Glauben kommt sie uns zugut. So hat Gott auch den Beweis erbracht, dass er gerecht gehandelt hatte, obwohl er die bis dahin begangenen Sünden der Menschen ungestraft ließ." },
      { number: 26, text: "Und heute beweist er seine Gerechtigkeit dadurch, dass er den für gerecht erklärt, der aus dem Glauben an Jesus lebt." },
      { number: 27, text: "Kann man da noch selbst auf etwas stolz sein? Das ist ausgeschlossen. Durch was für ein Gesetz kommt das? Durch das Gesetz, das Werke fordert? Nein! Es kommt durch das Gesetz, das auf den Glauben abzielt." },
      { number: 28, text: "Denn wir sind zu dem Schluss gekommen, dass ein Mensch durch Glauben für gerecht erklärt wird und nicht durch das Einhalten von Gesetzesvorschriften." },
      { number: 29, text: "Ist Gott denn nur ein Gott der Juden und nicht auch der Gott der anderen Völker? Natürlich auch der anderen Völker!" },
      { number: 30, text: "Denn es gibt nur den einen Gott. Er wird die Beschnittenen ebenso wie die Unbeschnittenen auf der gleichen Grundlage des Glaubens für gerecht erklären." },
      { number: 31, text: "Setzen wir nun aber durch den Glauben das Gesetz außer Kraft? Im Gegenteil: Wir bestätigen das Gesetz!" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Was hat denn bei unserem Stammvater Abraham – von dem wir Juden ja abstammen – dazu geführt,", heading: "Abraham der Vater des Glaubens" },
      { number: 2, text: "dass er für gerecht erklärt wurde? Etwa seine eigenen Leistungen? Dann hätte er Grund, stolz auf sich zu sein. Aber das zählt nichts vor Gott," },
      { number: 3, text: "denn die Schrift sagt: \"Abraham glaubte Gott, und das ist ihm als Gerechtigkeit angerechnet worden.\"*", footnotes: ["1. Mose 15,6"] },
      { number: 4, text: "Wenn jemand Leistungen erbracht hat, erhält er den Arbeitslohn, den er verdient. Er bekommt ihn nicht geschenkt." },
      { number: 5, text: "Wenn aber jemand keine Leistungen vorweisen kann, sondern sein Vertrauen auf den setzt, der den Gottlosen gerecht spricht, dann wird ihm sein Glaube als Gerechtigkeit angerechnet." },
      { number: 6, text: "Im gleichen Sinn nennt auch David den beneidenswert glücklich, dem Gott ohne Gegenleistung Gerechtigkeit zuspricht:" },
      { number: 7, text: "\"Wie glücklich ist der, dem die Übertretung des Gesetzes vergeben und dem die Sünde zugedeckt ist." },
      { number: 8, text: "Wie sehr ist der zu beneiden, dem der Herr die Sünde nicht anrechnet.\" *", footnotes: ["Psalm 32,1-2"] },
      { number: 9, text: "Werden hier nur die glücklich genannt, die beschnitten sind, oder gilt das auch für die Unbeschnittenen? Wir haben ja schon gesagt, dass Abraham der Glaube als Gerechtigkeit angerechnet wurde." },
      { number: 10, text: "Wann geschah das eigentlich? Als er beschnitten oder als er unbeschnitten war? Er war noch unbeschnitten!" },
      { number: 11, text: "Das Zeichen der Beschneidung besiegelte für ihn die Tatsache, dass Gott ihn schon vor seiner Beschneidung aufgrund seines Glaubens gerecht gesprochen hatte. Er sollte nämlich der Vater für alle werden, die Gott vertrauen, ohne beschnitten zu sein, und denen der Glaube als Gerechtigkeit angerechnet wird." },
      { number: 12, text: "Durch seine Beschneidung ist Abraham aber auch der Vater der Beschnittenen geworden, vor allem, wenn sie dem Beispiel des Glaubens folgen, den unser Vater Abraham hatte, als er noch unbeschnitten war." },
      { number: 13, text: "Dasselbe gilt für die Zusage, die Abraham und seinen Nachkommen die Welt als Besitz versprach. Diese Zusage wurde ihm nicht gegeben, weil er das Gesetz befolgte, sondern weil ihm aufgrund seines Glaubens die Gerechtigkeit zugesprochen wurde." },
      { number: 14, text: "Wenn dieser Besitz nämlich denen zugesprochen würde, die auf das Gesetz vertrauen, dann wäre der Glaube wertlos und die Zusage hinfällig." },
      { number: 15, text: "Denn das Gesetz führt durch seine ständige Übertretung nur zu Gottes Zorn. Wo es das Gesetz aber nicht gibt, da gibt es auch keine Übertretung." },
      { number: 16, text: "Das Prinzip des Glaubens gilt deshalb, damit alles auf Gnade beruhe. Nur so bleibt die Zusage für alle Nachkommen gültig, und zwar nicht nur für die, die nach dem Gesetz leben, sondern auch für die, die wie Abraham der Zusage Gottes vertrauen. So ist Abraham der Vater von uns allen," },
      { number: 17, text: "wie es in der Schrift heißt: \"Ich habe dich zum Vater vieler Völker gemacht.\"* Vor Gott ist er das auch, denn er vertraute auf den, der die Toten lebendig macht und das Nichtexistierende ins Dasein ruft.", footnotes: ["1. Mose 17,5"] },
      { number: 18, text: "Obwohl nichts mehr zu hoffen war, gab er die Hoffnung nicht auf und glaubte, dass Gott ihn zum Vater vieler Völker machen würde, denn er hatte ihm gesagt: \"So zahlreich werden deine Nachkommen sein.\"*", footnotes: ["1. Mose 15,5"] },
      { number: 19, text: "Obwohl er damals schon fast hundert Jahre alt war und wusste, dass er keine Kinder mehr zeugen und seine Frau Sara keine Kinder mehr bekommen könnte, wurde er im Glauben nicht schwach" },
      { number: 20, text: "und zweifelte nicht an der Zusage Gottes. Er ehrte Gott, indem er ihm vertraute, und wurde so im Glauben gestärkt." },
      { number: 21, text: "Er war sich völlig gewiss, dass Gott auch tun kann, was er verspricht." },
      { number: 22, text: "Eben darum wurde ihm der Glaube als Gerechtigkeit angerechnet." },
      { number: 23, text: "Dass Abraham der Glaube angerechnet wurde, steht aber nicht nur seinetwegen in der Schrift," },
      { number: 24, text: "sondern auch wegen uns. Auch uns wird der Glaube als Gerechtigkeit angerechnet werden, weil wir auf den vertrauen, der Jesus, unseren Herrn, aus den Toten auferweckt hat," },
      { number: 25, text: "ihn, der ausgeliefert wurde wegen unserer Verfehlungen und auferweckt wurde für unseren Freispruch." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Nachdem wir nun aufgrund des Glaubens für gerecht erklärt wurden, haben wir Frieden mit Gott durch unseren Herrn Jesus Christus.", heading: "5-8: Gerechtigkeit nur in (Verbindung mit) Christus\nIn Christus gerecht vor Gott (5)\nFür gerecht erklärt und mit Hoffnung erfüllt" },
      { number: 2, text: "Durch ihn haben wir auch freien Zugang zu der Gnade bekommen, in der wir jetzt leben. Das geschah im Glauben, und wir sind stolz auf die Hoffnung, mit der wir nun der Herrlichkeit Gottes entgegengehen dürfen." },
      { number: 3, text: "Aber nicht nur das: Wir sind auch stolz auf die Bedrückungen, denen wir ausgesetzt sind, denn wir wissen, dass wir durch Leiden Geduld lernen;" },
      { number: 4, text: "und wer Geduld gelernt hat, ist bewährt, und das wiederum festigt die Hoffnung." },
      { number: 5, text: "Und in dieser Hoffnung werden wir nicht enttäuscht, denn Gott hat uns mit dem Heiligen Geist, den er uns geschenkt hat, auch seine Liebe ins Herz ausgegossen." },
      { number: 6, text: "Christus ist ja schon zu einer Zeit gestorben, als wir noch ohnmächtig der Sünde ausgeliefert waren. Und er starb für gottlose Menschen." },
      { number: 7, text: "Nun wird sich kaum jemand finden, der für einen Gerechten stirbt; eher noch würde sich jemand für einen besonders gütigen Menschen opfern." },
      { number: 8, text: "Aber Gott hat seine Liebe zu uns dadurch bewiesen, dass Christus für uns starb, als wir noch Sünder waren." },
      { number: 9, text: "Und nachdem wir jetzt durch sein Blut gerechtfertigt sind, werden wir durch ihn erst recht vor dem kommenden Strafgericht gerettet." },
      { number: 10, text: "Denn durch den Tod seines Sohnes hat Gott uns ja schon versöhnt, als wir noch seine Feinde waren. Deshalb werden wir jetzt, nachdem wir versöhnt sind, erst recht durch die Kraft seines Lebens gerettet werden." },
      { number: 11, text: "Aber es ist nicht nur diese Hoffnung, die uns mit Stolz und Freude erfüllt, sondern auch die Beziehung zu Gott, die uns durch Jesus Christus geschenkt ist. Denn durch ihn sind wir schon jetzt mit Gott versöhnt." },
      { number: 12, text: "Durch einen einzigen Menschen ist die Sünde in die Welt gekommen und mit der Sünde der Tod. Und auf diese Weise ist der Tod zu allen Menschen hingekommen. Deswegen hat auch jeder gesündigt.", heading: "Christus anstelle von Adam" },
      { number: 13, text: "Selbst als es das Gesetz noch nicht gab, war die Sünde schon in der Welt. Doch wird sie da, wo es kein Gesetz gibt, nicht als Schuld angerechnet." },
      { number: 14, text: "Trotzdem herrschte schon in der Zeit zwischen Adam und Mose der Tod auch über die Menschen, die kein ausdrückliches Gebot übertraten, also nicht in derselben Weise wie Adam sündigten. Mit seinem Ungehorsam ist Adam das genaue Gegenteil von dem, der kommen soll." },
      { number: 15, text: "Doch die Begnadigung ist nicht einfach ein Gegenstück für die Übertretung. Denn wenn die Übertretung eines Einzigen der ganzen Menschheit den Tod brachte, so wird das durch die Gnade Gottes mehr als aufgewogen, denn die ganze Menschheit wird durch die Gnade eines einzigen Menschen, nämlich durch Jesus Christus, überaus reich beschenkt." },
      { number: 16, text: "Dieses Geschenk ist nicht vergleichbar mit dem, was durch den einen Sünder verursacht wurde. Denn das Urteil Gottes, das der Übertretung des einen folgte, führt zur Verdammnis. Aber der Gnadenerweis, der auf zahllose Verfehlungen folgte, führt zum Freispruch." },
      { number: 17, text: "Ist durch die Verfehlung eines Einzigen der Tod zur Herrschaft gekommen, so werden erst recht alle, die Gottes Gnade und das Geschenk der Gerechtigkeit in so reichem Maß empfangen haben, durch den Einen, durch Jesus Christus, leben und herrschen." },
      { number: 18, text: "So wie eine einzige Verfehlung allen Menschen die Verdammnis brachte, so bringt eine einzige Tat, die Gottes Rechtsforderung erfüllte, allen Menschen den Freispruch und das Leben." },
      { number: 19, text: "Genauso wie durch den Ungehorsam eines einzigen Menschen alle zu Sündern wurden, so werden durch den Gehorsam eines Einzigen alle zu Gerechten." },
      { number: 20, text: "Das Gesetz ist erst nachträglich dazugekommen, um die Tragweite der Übertretungen deutlich zu machen. Und gerade dort, wo sich die ganze Macht der Sünde zeigte, ist die Gnade noch sehr viel mächtiger geworden." },
      { number: 21, text: "Denn genauso wie die Sünde geherrscht und den Menschen den Tod gebracht hat, soll die Gnade herrschen und uns durch die geschenkte Gerechtigkeit zum ewigen Leben führen durch Jesus Christus, unseren Herrn." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Was heißt das nun? Sollen wir an der Sünde festhalten, damit die Gnade sich noch mächtiger auswirken kann?", heading: "In Christus frei von der Sünde (6)\nFrei von der Sklaverei der Sünde" },
      { number: 2, text: "Auf keinen Fall! Für die Sünde sind wir doch schon gestorben, wie können wir da noch in ihr leben?" },
      { number: 3, text: "Oder wisst ihr nicht, dass alle von uns, die auf Jesus Christus getauft wurden, in seinen Tod mit eingetaucht worden sind?" },
      { number: 4, text: "Durch die Taufe sind wir also mit Christus in den Tod hinein begraben worden, damit so, wie Christus durch die herrliche Macht des Vaters von den Toten auferweckt wurde, wir nun ebenfalls in dieser neuen Wirklichkeit leben." },
      { number: 5, text: "Denn wenn wir mit seinem Tod vereinigt worden sind, werden wir auch eins mit seiner Auferstehung sein." },
      { number: 6, text: "Wir sollen also begreifen, dass unser alter Mensch mit Christus gekreuzigt worden ist, damit unser sündiges Wesen unwirksam gemacht wird und wir der Sünde nicht mehr wie Sklaven dienen." },
      { number: 7, text: "Denn wer gestorben ist, ist vom Herrschaftsanspruch der Sünde befreit." },
      { number: 8, text: "Wenn wir nun mit Christus gestorben sind, vertrauen wir darauf, dass wir auch mit ihm leben werden." },
      { number: 9, text: "Wir wissen ja, dass Christus von den Toten auferweckt wurde und nie mehr stirbt. Der Tod hat keine Gewalt mehr über ihn." },
      { number: 10, text: "Denn sein Sterben war ein Sterben für die Sünde, und zwar ein für alle Mal. Aber sein Leben ist ein Leben für Gott." },
      { number: 11, text: "Auch ihr sollt von dieser Tatsache ausgehen, dass ihr für die Sünde tot seid, aber in Jesus Christus für Gott lebt." },
      { number: 12, text: "Die Sünde soll euren vergänglichen Körper also nicht mehr beherrschen und euch dazu bringen, seinen Begierden zu gehorchen." },
      { number: 13, text: "Und stellt eure Glieder nicht mehr der Sünde zur Verfügung als Werkzeuge des Unrechts, sondern stellt euch selbst Gott zur Verfügung als Menschen, die vom Tod zum Leben gekommen sind, und bietet ihm eure Glieder als Werkzeuge der Gerechtigkeit an." },
      { number: 14, text: "Dann wird die Sünde ihre Macht über euch verlieren, denn ihr lebt ja nicht mehr unter dem Gesetz, sondern unter der Gnade." },
      { number: 15, text: "Heißt das nun, dass wir einfach weiter sündigen, weil wir nicht mehr unter der Herrschaft des Gesetzes, sondern unter der Gnade stehen? Auf keinen Fall!" },
      { number: 16, text: "Überlegt doch einmal: Wenn ihr euch jemand unterstellt und als Sklaven zum Gehorsam verpflichtet, dann seid ihr damit seine Sklaven. Entweder seid ihr Sklaven der Sünde, dann wird euch das zum Tod führen, oder ihr gehorcht Gott und werdet zur Gerechtigkeit geführt." },
      { number: 17, text: "Aber Gott sei Dank: Ihr, als frühere Sklaven der Sünde, gehorcht jetzt von Herzen der Lehre, von der ihr inzwischen geprägt worden seid." },
      { number: 18, text: "Von der Sünde befreit seid ihr nun in den Dienst der Gerechtigkeit gestellt." },
      { number: 19, text: "Ich gebrauche das Bild vom Sklavendienst, damit ihr versteht, was ich meine. Früher hattet ihr eure Glieder in den Sklavendienst von Unmoral und Zügellosigkeit gestellt und führtet ein Leben gegen Gottes Gesetz. Jetzt sollt ihr eure Glieder in den Dienst der Gerechtigkeit stellen, was euch zu einem Leben in Übereinstimmung mit Gott führt." },
      { number: 20, text: "Als ihr Sklaven der Sünde wart, wart ihr von jeder Gerechtigkeit frei." },
      { number: 21, text: "Und was kam dabei heraus? Ihr habt Dinge getan, für die ihr euch jetzt schämt und die euch letztlich nur den Tod gebracht hätten." },
      { number: 22, text: "Aber jetzt seid ihr vom Dienst der Sünde befreit und Sklaven Gottes geworden. Das bringt euch den Gewinn eines geheiligten Lebens und im Endergebnis das ewige Leben." },
      { number: 23, text: "Denn der Gewinn aus der Sünde ist nur der Tod; das Gnadengeschenk Gottes aber ist das ewige Leben in Jesus Christus, unserem Herrn." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Nun ist euch doch klar, liebe Geschwister – ich rede ja zu Leuten, die das Gesetz kennen –, dass das Gesetz für einen Menschen nur so lange Geltung hat, wie er lebt.", heading: "In Christus frei vom Gesetz (7)\nFrei von der Herrschaft des Gesetzes" },
      { number: 2, text: "So ist zum Beispiel eine verheiratete Frau durch das Gesetz an ihren Mann gebunden, so lange er lebt. Stirbt ihr Mann, ist sie frei von dem Gesetz, das sie an ihn band." },
      { number: 3, text: "Wenn sie sich also zu Lebzeiten ihres Mannes mit einem anderen einlässt, gilt sie als Ehebrecherin. Stirbt aber der Mann, ist sie nicht mehr durch das Gesetz gebunden. Es steht ihr frei, einen anderen zu heiraten. Sie wird deswegen nicht zur Ehebrecherin." },
      { number: 4, text: "So ist es auch mit euch, liebe Geschwister. Durch den körperlichen Tod des Messias seid ihr dem Gesetz gegenüber zu Tode gekommen, so dass ihr jetzt einem anderen angehören könnt, nämlich dem, der von den Toten auferweckt wurde. Und das bedeutet: Jetzt kann unser Leben für Gott Frucht bringen." },
      { number: 5, text: "Denn als wir noch unserem natürlichen Wesen folgten, war alles, was wir taten, von den durch das Gesetz erregten sündigen Leidenschaften bestimmt. Die einzige Frucht, die das brachte, war der Tod." },
      { number: 6, text: "Doch jetzt sind wir vom Gesetz freigekommen, wir sind tot für das Gesetz, das uns früher gefangen hielt. Jetzt stehen wir im Dienst einer neuen Ordnung, der des Geistes, und werden nicht mehr von der alten beherrscht, die vom Buchstaben des Gesetzes bestimmt war." },
      { number: 7, text: "Heißt das nun, dass das Gesetz Sünde ist? Auf keinen Fall! Aber ohne Gesetz hätte ich nie erkannt, was Sünde ist. Auch die Begierde wäre nie in mir erwacht, wenn das Gesetz nicht gesagt hätte: \"Du sollst nicht begehren!\"*", footnotes: ["2. Mose 20,17"] },
      { number: 8, text: "Doch die Sünde nutzte die Gelegenheit und stachelte durch das Gebot jede Begierde in mir auf. Ohne Gesetz ist die Sünde tot." },
      { number: 9, text: "Ich dagegen lebte, solange ich noch ohne Gesetz war. Als dann aber das Gebot kam, fing die Sünde an zu leben –" },
      { number: 10, text: "und ich starb. Das Gebot, das mir das Leben erhalten sollte, brachte mir den Tod." },
      { number: 11, text: "Denn die Sünde ergriff die Gelegenheit und benutzte das Gesetz, um mich zu täuschen und zu töten." },
      { number: 12, text: "Es bleibt also dabei: Das Gesetz ist heilig, und seine Forderungen sind heilig, gerecht und gut." },
      { number: 13, text: "Hat nun das Gute mir den Tod gebracht? Auf keinen Fall! Schuld war die Sünde. Sie hat mir den Tod gebracht und das Gute dazu benutzt. So hat sie ihr wahres Gesicht gezeigt. Die Forderungen des Gesetzes haben nur die Abscheulichkeit der Sünde ans Licht gebracht." },
      { number: 14, text: "Wir wissen ja, dass das Gesetz vom Geist Gottes erfüllt ist. Ich dagegen bin von meiner Natur bestimmt und der Sünde unterworfen." },
      { number: 15, text: "Ich verstehe ja selbst nicht, was ich tue. Denn ich tue nicht das, was ich will, sondern gerade das, was ich hasse." },
      { number: 16, text: "Wenn ich aber das tue, was ich gar nicht tun will, gebe ich dem Gesetz Recht und heiße es gut." },
      { number: 17, text: "Dann aber bin nicht mehr ich es, der so handelt, sondern die Sünde, die in mir wohnt." },
      { number: 18, text: "Denn ich weiß, dass in mir, das heißt in meiner Natur, nichts Gutes wohnt. Es fehlt mir nicht am Wollen, aber ich bringe es nicht fertig, das Gute zu tun." },
      { number: 19, text: "Ich tue nicht das Gute, das ich tun will, sondern das Böse, das ich nicht will." },
      { number: 20, text: "Wenn ich aber das tue, was ich gar nicht will, dann bin nicht mehr ich der Handelnde, sondern die Sünde, die in mir wohnt." },
      { number: 21, text: "Ich stelle also ein Gesetz des Bösen in mir fest, obwohl ich doch das Gute tun will." },
      { number: 22, text: "Denn meiner innersten Überzeugung nach stimme ich dem Gesetz Gottes freudig zu," },
      { number: 23, text: "aber in meinen Gliedern sehe ich ein anderes Gesetz wirken, das mit dem Gesetz in meinem Innern in Streit liegt und mich zu seinem Gefangenen macht: das Gesetz der Sünde." },
      { number: 24, text: "Ich unglückseliger Mensch! Gibt es denn niemand, der mich aus dieser tödlichen Verstrickung befreit?" },
      { number: 25, text: "Doch! Und dafür danke ich Gott durch Jesus Christus, unseren Herrn.Es gilt also beides: Meiner innersten Überzeugung nach diene ich dem Gesetz Gottes, meiner Natur nach aber bin ich dem Gesetz der Sünde versklavt." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Es gibt demnach kein Verdammungsurteil mehr für die, die ganz mit Jesus Christus verbunden* sind.", heading: "In Christus frei für den Geist (8)\nDer Gottesgeist regiert mein Leben", footnotes: ["ganz mit Jesus Christus verbunden. Wörtlich: in Christus Jesus."] },
      { number: 2, text: "Denn das Gesetz des Geistes, das dich mit Jesus Christus zum Leben führt, hat dich von dem Gesetz befreit, das nur Sünde und Tod bringt." },
      { number: 3, text: "Das Gesetz des Mose war dazu nicht imstande. Es scheiterte am Widerstand unserer Natur. Deshalb hat Gott seinen Sohn gegen die Sünde in die Welt geschickt. Er kam in der gleichen Gestalt, wie sie die Menschen haben, die im Widerspruch zu Gott leben, und machte der Sünde in der menschlichen Natur den Prozess." },
      { number: 4, text: "Damit kann jetzt die Rechtsforderung des göttlichen Gesetzes in uns erfüllt werden, und zwar dadurch, dass wir uns nicht mehr von unserer Natur, sondern vom Geist Gottes bestimmen lassen." },
      { number: 5, text: "Denn alle, die sich von ihrer Natur bestimmen lassen, sind auf das bedacht, was ihre eigene Natur will. Wer sich aber vom Geist Gottes bestimmen lässt, ist auf das ausgerichtet, was der Geist will." },
      { number: 6, text: "Was die menschliche Natur will, bringt den Tod, was aber der Geist will, bringt Leben und Frieden." },
      { number: 7, text: "Denn der menschliche Eigenwille steht dem Willen Gottes feindlich gegenüber, denn er unterstellt sich dem Gesetz Gottes nicht und kann das auch nicht." },
      { number: 8, text: "Wer also von seiner eigenen Natur bestimmt ist, kann Gott nicht gefallen." },
      { number: 9, text: "Ihr jedoch steht nicht mehr unter der Herrschaft eurer Natur, sondern unter der des Geistes, wenn wirklich Gottes Geist in euch wohnt. Denn wenn jemand diesen Geist von Christus nicht hat, gehört er nicht zu ihm." },
      { number: 10, text: "Wenn nun also Christus in euch ist, bleibt der Körper zwar dem Tod verfallen aufgrund der Sünde, der Geist aber erfüllt euch mit Leben aufgrund der Gerechtigkeit, die Gott euch geschenkt hat." },
      { number: 11, text: "Wenn nun der Geist von dem in euch wohnt, der Jesus aus den Toten auferweckt hat, dann wird er durch den Geist, der in euch wohnt, auch euren sterblichen Körper lebendig machen, eben weil er Christus aus den Toten auferweckt hat." },
      { number: 12, text: "Darum sind wir jetzt nicht mehr unserer eigenen Natur verpflichtet, liebe Geschwister, als müssten wir uns von ihr bestimmen lassen!" },
      { number: 13, text: "Denn wenn ihr euer Leben von eurer Natur bestimmen lasst, werdet ihr sterben. Wenn ihr aber durch den Geist die alten Verhaltensweisen tötet, werdet ihr leben." },
      { number: 14, text: "Denn diejenigen, die von Gottes Geist gelenkt werden, sind Kinder Gottes." },
      { number: 15, text: "Der Geist, den ihr empfangen habt, macht euch ja nicht wieder zu Sklaven, dass ihr wie früher in Furcht leben müsstet. Nein, ihr habt den Geist empfangen, der euch zu Kindern Gottes macht, den Geist, in dem wir \"Abba Vater!\"* zu Gott sagen.", footnotes: ["Abba (aramäisch) bedeutet Vater. Der Ausdruck wurde als liebe- und respektvolle Anrede nur im Familienkreis gebraucht."] },
      { number: 16, text: "So macht sein Geist uns im Innersten gewiss, dass wir Kinder Gottes sind." },
      { number: 17, text: "Wenn wir aber Kinder sind, dann sind wir auch Erben, Erben Gottes und Miterben mit Christus, die jetzt mit ihm leiden, um dann auch an seiner Herrlichkeit teilzuhaben." },
      { number: 18, text: "Übrigens meine ich, dass die Leiden der jetzigen Zeit im Vergleich zu der Herrlichkeit, die an uns sichtbar werden wird, überhaupt nicht ins Gewicht fallen.", heading: "Die ganze Schöpfung darf hoffen" },
      { number: 19, text: "Die gesamte Schöpfung wartet ja sehnsüchtig auf den Tag, an dem die Kinder Gottes in ihrer ganzen Herrlichkeit erkennbar werden." },
      { number: 20, text: "Denn die Schöpfung ist gegen ihren Willen der Nichtigkeit unterworfen worden. Sie musste sich dem beugen, der sie unterworfen hat. Allerdings hat sie eine Hoffnung:" },
      { number: 21, text: "Auch die Schöpfung wird von der Versklavung in die Vergänglichkeit zur Herrlichkeit der Kinder Gottes befreit werden." },
      { number: 22, text: "Denn wir wissen, dass die gesamte Schöpfung bis heute unter ihrem Zustand seufzt, als würde sie in Geburtswehen liegen." },
      { number: 23, text: "Aber nicht nur das, auch wir selbst, denen Gott doch schon seinen Geist gegeben hat – als Vorschuss auf das künftige Erbe –, auch wir seufzen innerlich und warten sehnsüchtig auf das Offenbarwerden unserer Kindschaft: die Erlösung unseres Körpers." },
      { number: 24, text: "Denn mit dieser Hoffnung sind wir gerettet worden. Aber eine Hoffnung, die man schon erfüllt sieht, ist keine Hoffnung. Denn warum sollte man auf etwas hoffen, was man schon verwirklicht sieht?" },
      { number: 25, text: "Wenn wir aber auf etwas hoffen, was wir noch nicht sehen können, warten wir geduldig, bis es sich erfüllt." },
      { number: 26, text: "In gleicher Weise nimmt sich der Geist Gottes auch unserer Schwachheit an, denn wir wissen nicht, wie man richtig beten soll. Er tritt mit einem Seufzen für uns ein, das man nicht in Worte fassen kann." },
      { number: 27, text: "Und Gott, der die Herzen erforscht, weiß, was der Geist damit sagen will, denn der Geist tritt für die Heiligen* so ein, wie es vor Gott angebracht ist.", footnotes: ["Heilige. Gemeint sind die Christen, alle, die zu dem heiligen Gott gehören."] },
      { number: 28, text: "Wir wissen aber, dass Gott bei denen, die ihn lieben, alles zum Guten mitwirken lässt. Das sind ja die Menschen, die er nach seinem freien Entschluss berufen hat.", heading: "Wenn Gott für uns ist ..." },
      { number: 29, text: "Denn sie, die er im Voraus erwählt hat, die hat er auch im Voraus dazu bestimmt, in Wesen und Gestalt seinem Sohn gleich zu werden, denn er sollte der Erstgeborene unter vielen Brüdern sein." },
      { number: 30, text: "Und alle, die er dazu erwählt hat, die hat er auch berufen, und die er berufen hat, die hat er auch für gerecht erklärt, und die er für gerecht erklärt hat, denen hat er auch Anteil an seiner Herrlichkeit gegeben." },
      { number: 31, text: "Was sollen wir jetzt noch dazu sagen? Wenn Gott für uns ist, wer könnte dann gegen uns sein?" },
      { number: 32, text: "Er hat nicht einmal seinen eigenen Sohn verschont, sondern ihn für uns alle ausgeliefert: Wird er uns dann noch irgendetwas vorenthalten?" },
      { number: 33, text: "Wer wird es wagen, diese Auserwählten Gottes anzuklagen? Gott selbst erklärt sie ja für gerecht." },
      { number: 34, text: "Wer kann sie verurteilen? Jesus Christus ist doch für sie gestorben, ja noch mehr: Er ist auferweckt und sitzt an Gottes rechter Seite und tritt dort für uns ein." },
      { number: 35, text: "Was kann uns da noch von Christus und seiner Liebe trennen? Bedrängnis? Angst? Verfolgung? Hunger? Kälte? Lebensgefahr? Das Schwert des Henkers?" },
      { number: 36, text: "Es kann uns so ergehen, wie es in der Schrift heißt: \"Weil wir zu dir gehören, sind wir mit dem Tod bedroht; man behandelt uns wie Schafe, die zum Schlachten bestimmt sind.\"*", footnotes: ["Psalm 44,23"] },
      { number: 37, text: "Aber durch den, der uns geliebt hat, sind wir in all diesen Dingen überlegene Sieger." },
      { number: 38, text: "Denn ich bin überzeugt: Weder Tod noch Leben, weder Engel noch Teufel, weder Gegenwärtiges noch Zukünftiges," },
      { number: 39, text: "weder hohe Kräfte noch tiefe Gewalten – nichts in der ganzen Schöpfung kann uns von der Liebe Gottes trennen, die uns verbürgt ist in Jesus Christus, unserem Herrn." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Was ich jetzt sage, sage ich vor Christus. Mein Gewissen bestätigt es, und der Heilige Geist bezeugt mir, dass es die Wahrheit ist:", heading: "9-11: Gerechtigkeit auch für das Volk Israel\nAbhängig vom Willen Gottes (9)\nIsrael und Gottes Versprechen" },
      { number: 2, text: "Mein Herz ist von tiefer Traurigkeit erfüllt, und es quält mich unablässig," },
      { number: 3, text: "wenn ich an die Angehörigen meines Volkes denke, an meine Brüder und Schwestern, mit denen ich durch die gemeinsame Abstammung verbunden bin. Für sie hätte ich es auf mich genommen, verflucht und für immer von Christus getrennt zu sein." },
      { number: 4, text: "Sie sind ja Israeliten; ihnen hat Gott das Vorrecht geschenkt, seine Kinder zu sein. Ihnen hat er seine Herrlichkeit gezeigt; mit ihnen hat er seine Bündnisse geschlossen; ihnen hat er das Gesetz und die Ordnungen des Gottesdienstes gegeben; ihnen gelten seine Zusagen." },
      { number: 5, text: "Sie sind die Nachkommen der von Gott erwählten Väter, und aus ihrer Mitte ist auch der Messias seiner menschlichen Herkunft nach hervorgegangen. Er ist Gott, der über allem steht und für immer und ewig zu preisen ist. Amen!" },
      { number: 6, text: "Ich will damit nicht gesagt haben, dass das von Gott gegebene Wort keine Gültigkeit mehr hätte. Aber es gehören eben nicht alle Israeliten zum eigentlichen Israel." },
      { number: 7, text: "Nicht weil sie von Abraham abstammen, sind sie seine Kinder, denn Gott sagte zu ihm: \"Durch Isaak gebe ich dir die Nachkommen, die ich dir versprochen habe.\"*", footnotes: ["1. Mose 21,12"] },
      { number: 8, text: "Mit anderen Worten: Nicht die Abstammung macht zu Gottes Kindern, sondern die göttliche Zusage führt zur eigentlichen Nachkommenschaft." },
      { number: 9, text: "Die Zusage lautete: \"In einem Jahr werde ich wiederkommen, und dann wird Sara einen Sohn haben.\"*", footnotes: ["1. Mose 18,10.14"] },
      { number: 10, text: "Aber nicht nur bei ihr, sondern auch bei Rebekka war es so, als sie von unserem Stammvater Isaak schwanger war." },
      { number: 11, text: "Denn als die Zwillinge noch nicht geboren waren und noch nichts Gutes oder Böses getan hatten – damit sollte der Plan Gottes bekräftigt werden, dass seine Wahl nicht von menschlichen Leistungen abhängig ist, sondern allein von seiner freien Entscheidung –," },
      { number: 12, text: "sagte Gott zu Rebekka: \"Der Ältere wird dem Jüngeren dienen.\"*", footnotes: ["1. Mose 25,23"] },
      { number: 13, text: "Darum heißt es auch in der Schrift: \"Jakob habe ich meine Liebe geschenkt, aber Esau habe ich von mir gestoßen.\"*", footnotes: ["Maleachi 1,2-3"] },
      { number: 14, text: "Heißt das nun, dass Gott ungerecht ist? Auf keinen Fall!", heading: "Gott schenkt sein Erbarmen, wem er will" },
      { number: 15, text: "Er sagte ja zu Mose: \"Ich schenke mein Erbarmen dem, über den ich mich erbarmen will, und mein Mitleid dem, den ich bemitleiden will.\"*", footnotes: ["2. Mose 33,19"] },
      { number: 16, text: "Es kommt also nicht auf das Wollen und Bemühen eines Menschen an, sondern allein auf Gott und sein Erbarmen." },
      { number: 17, text: "Auch wird in der Schrift zum Pharao gesagt: \"Nur deshalb habe ich dich als Herrscher auftreten lassen, um dir meine Macht zu demonstrieren und meinen Namen in der ganzen Welt bekannt zu machen.\"*", footnotes: ["2. Mose 9,16"] },
      { number: 18, text: "Wir sehen also: Gott handelt ganz nach seinem Ermessen: Dem einen schenkt er sein Erbarmen, den anderen macht er starrsinnig und lässt ihn ins Verderben laufen." },
      { number: 19, text: "Nun wirst du einwenden: \"Wie kann er uns dann noch Vorwürfe machen? Es kann sich doch niemand seinem Willen widersetzen!\"" },
      { number: 20, text: "So? Wer bist du eigentlich? Du Mensch willst anfangen, mit Gott zu streiten? Sagt das Werk zu seinem Meister: \"Warum hast du mich so gemacht?\"" },
      { number: 21, text: "Ist der Töpfer nicht Herr über den Ton und kann aus derselben Masse ein Gefäß machen, das auf der Festtafel zu Ehren kommt, und ein anderes, das für den Abfall dienen soll?" },
      { number: 22, text: "Und was sagst du dazu, dass Gott die Gefäße, die zur Vernichtung in seinem Zorngericht bereitgestellt sind, mit großer Geduld erträgt? Er will zwar, dass sie seinen Zorn und seine Macht zu spüren bekommen," },
      { number: 23, text: "andererseits will er aber auch an den Gefäßen, die er in seinem Erbarmen zur Herrlichkeit vorherbestimmt hat, zeigen, wie unerschöpflich reich seine Herrlichkeit ist." },
      { number: 24, text: "Das sind nämlich wir, die er nicht nur aus dem jüdischen Volk, sondern auch aus anderen Völkern berufen hat." },
      { number: 25, text: "Das hat er schon durch den Propheten Hosea angekündigt: \"Ich werde als mein Volk berufen, was nicht mein Volk war, und als geliebte Frau die, die nicht geliebt war.\"*", footnotes: ["Hosea 2,25"] },
      { number: 26, text: "\"Gerade dort, wo zu ihnen gesagt wurde: 'Ihr seid nicht mein Volk', werden sie 'Kinder des lebendigen Gottes' genannt werden.\"*", footnotes: ["Hosea 2,1"] },
      { number: 27, text: "Und Jesaja ruft über Israel aus: \"Selbst wenn es Israeliten gäbe wie Sand am Meer, nur ein Rest von ihnen wird gerettet werden." },
      { number: 28, text: "Denn der Herr wird auf der Erde handeln. Er wird sein Wort einlösen und rasch durchsetzen.\"*", footnotes: ["Jesaja 10,22-23"] },
      { number: 29, text: "Es ist so, wie es Jesaja an anderer Stelle vorausgesagt hat: \"Hätte der Herr, der allmächtige Gott, nicht einen Rest von unserem Volk übrig gelassen, so wäre es uns wie Sodom und Gomorra ergangen.\"*", footnotes: ["Jesaja 1,9 nach der LXX zitiert."] },
      { number: 30, text: "Was heißt das nun? Menschen aus allen Völkern sind vor Gott gerecht geworden, ohne sich darum bemüht zu haben. Sie haben die Gerechtigkeit erhalten, die aus dem Glauben kommt." },
      { number: 31, text: "Das Volk Israel aber, das durch das Gesetz gerecht werden wollte, hat das Ziel des Gesetzes nicht erreicht." },
      { number: 32, text: "Und warum nicht? Weil sie meinten, es durch ihre eigenen Leistungen zu erreichen und nicht durch den Glauben. Sie haben sich am \"Stein des Anstoßes\" gestoßen," },
      { number: 33, text: "von dem geschrieben steht: \"Seht her, ich lege in Zion einen Grundstein, an dem man sich stoßen wird, einen Felsblock, an dem man zu Fall kommt. Doch wer ihm vertraut, wird nicht enttäuscht werden.\"*", footnotes: ["Jesaja 8,14; 28,16"] },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Liebe Geschwister, ich wünsche von Herzen und flehe zu Gott, dass die Angehörigen meines Volkes gerettet werden.", heading: "Abhängig vom Glauben an Christus (10)\nDie Rettung kommt nur durch den Glauben" },
      { number: 2, text: "Denn ich kann ihnen bezeugen, dass sie sich mit großem Eifer für Gott einsetzen. Doch was ihnen fehlt, ist die richtige Erkenntnis." },
      { number: 3, text: "Sie begreifen nicht, worum es bei der Gerechtigkeit Gottes geht, und versuchen, durch ihre eigene Gerechtigkeit vor Gott zu bestehen. Damit haben sie sich der Gerechtigkeit, die Gott ihnen schenken will, verweigert." },
      { number: 4, text: "Denn mit Christus ist der Weg des Gesetzes zu Ende. Jetzt wird jeder, der an ihn glaubt, für gerecht erklärt." },
      { number: 5, text: "Mose beschreibt die Gerechtigkeit, die auf dem Gesetz beruht, so: \"Wer sich nach seinen Vorschriften gerichtet hat, gewinnt das Leben.\"*", footnotes: ["3. Mose 18,5 nach der LXX zitiert."] },
      { number: 6, text: "Aber die Gerechtigkeit, die auf dem Glauben beruht, sagt: \"Du musst dich nicht fragen: 'Kann denn jemand in den Himmel hinaufsteigen?'\" – als müsste man Christus von dort herabholen –," },
      { number: 7, text: "\"oder: 'Kann jemand in den Abgrund hinuntersteigen?'\" – als müsste man Christus von den Toten heraufholen." },
      { number: 8, text: "Im Gegenteil, sie sagt: \"Das Wort ist dir ganz nahe. Es ist in deinem Mund und in deinem Herzen.\"* Mit diesem Wort ist die Botschaft vom Glauben gemeint, die wir predigen.", footnotes: ["Die Zitate stammen alle aus 5. Mose 30,12-14."] },
      { number: 9, text: "Wenn du mit deinem Mund bekennst, dass Jesus der Herr ist, und in deinem Herzen glaubst, dass Gott ihn aus den Toten auferweckt hat, wirst du gerettet werden." },
      { number: 10, text: "Denn man wird für gerecht erklärt, wenn man mit dem Herzen glaubt, man wird gerettet, wenn man seinen Glauben mit dem Mund bekennt." },
      { number: 11, text: "Denn die Schrift sagt: \"Wer ihm vertraut, wird nicht enttäuscht werden.\"*", footnotes: ["Jesaja 28,16"] },
      { number: 12, text: "Es gibt da keinen Unterschied zwischen Juden und Nichtjuden, denn sie haben alle denselben Herrn und er lässt alle an seinem Reichtum Anteil haben, alle, die ihn anrufen." },
      { number: 13, text: "Denn \"jeder, der den Namen des Herrn anruft, wird gerettet werden.\"*", footnotes: ["Joel 3,5. Den Namen Gottes, der bei Joel Jahwe lautet, bezieht Paulus hier eindeutig auf den Herrn Jesus Christus (vergleiche die Verse 9-12). Petrus tut das ebenso in Apostelgeschichte 2,21."] },
      { number: 14, text: "Doch wie sollen sie den anrufen, an den sie nicht glauben? Und wie sollen sie an den glauben, von dem sie nichts gehört haben? Und wie sollen sie von ihm hören, wenn ihnen keiner die Botschaft bringt?" },
      { number: 15, text: "Aber wie soll die Botschaft verkündigt werden, wenn niemand den Auftrag dazu bekommen hat? Doch das ist geschehen. Es ist eingetroffen, was geschrieben steht: \"Was für eine Freude ist es, wenn die Boten kommen und die gute Nachricht bringen.\"*", footnotes: ["Jesaja 52,7; Nahum 2,1"] },
      { number: 16, text: "Leider haben nicht alle diese gute Nachricht angenommen. Schon Jesaja sagt: \"Herr, wer hat unserer Botschaft geglaubt?\"*", footnotes: ["Jesaja 53,1."] },
      { number: 17, text: "Der Glaube kommt also aus dem Hören der Botschaft und die Verkündigung aus dem Wort von Christus." },
      { number: 18, text: "Nun frage ich: \"Haben sie die Botschaft etwa nicht gehört?\" Aber natürlich haben sie sie gehört! \"Ihr Ruf ging ja über die ganze Erde, die Nachricht ist bis in die entlegensten Ecken der Welt gekommen.\"*", footnotes: ["Psalm 19,5."] },
      { number: 19, text: "Ich frage weiter: \"Hat Israel sie etwa nicht verstanden?\" Die Antwort steht schon bei Mose: \"Ich werde euch eifersüchtig machen über ein Nicht-Volk. Ich werde euch zum Zorn über eine Nation reizen, die gar nichts von mir weiß.\"*", footnotes: ["5.Mose 32,21."] },
      { number: 20, text: "Und Jesaja wagt sogar zu sagen: \"Ich ließ mich von denen finden, die nicht einmal nach mir suchten, ich habe mich denen gezeigt, die nicht nach mir fragten.\"*", footnotes: ["Jesaja 65,1"] },
      { number: 21, text: "Über Israel aber sagt er: \"Den ganzen Tag habe ich meine Hände nach einem Volk ausgestreckt, das ungehorsam und widerspenstig ist.\"*", footnotes: ["Jesaja 65,2"] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Ich frage nun: \"Hat Gott sein Volk etwa verstoßen?\" Auf keinen Fall! Ich bin ja selbst ein Israelit, ein Nachkomme Abrahams aus dem Stamm Benjamin.", heading: "Abhängig von der Erwählung (11)\nGott hat sein Volk nicht verstoßen" },
      { number: 2, text: "Nein, Gott hat sein Volk nicht verstoßen. Er hat es doch von Anfang an erwählt. Oder wisst ihr nicht, was die Schrift von Elija sagt, als er sich bei Gott über das Volk beklagt?" },
      { number: 3, text: "\"Herr, sie haben deine Propheten getötet und deine Altäre niedergerissen. Ich allein bin übrig geblieben und nun wollen sie auch mich noch töten.\"*", footnotes: ["1. Könige 19,10.14"] },
      { number: 4, text: "Und was gab Gott ihm zur Antwort? \"Ich habe 7000 Männer für mich übrig gelassen, die sich nicht vor dem Götzen Baal auf die Knie geworfen haben.\"*", footnotes: ["1. Könige 19,18"] },
      { number: 5, text: "So ist es auch jetzt: Gott hat einen Rest von seinem Volk übrig gelassen, einen Rest, den er aus Gnade ausgewählt hat –" },
      { number: 6, text: "aus Gnade, also nicht aufgrund von Werken, sonst wäre die Gnade ja nicht mehr Gnade." },
      { number: 7, text: "Was heißt das nun? Was Israel erstrebt, hat nicht das ganze Volk, sondern nur der ausgewählte Rest erlangt. Die Übrigen sind starrsinnig geworden," },
      { number: 8, text: "wie die Schrift sagt: \"Gott hat einen Geist der Betäubung über sie kommen lassen. Sie haben Augen, die nicht sehen, und Ohren, die nicht hören, und so ist es bis zum heutigen Tag.\"*", footnotes: ["5. Mose 29,3"] },
      { number: 9, text: "Und David sagt: \"Ihre Opfer sollen ihnen zur Schlinge und zum Fangnetz werden, zur Falle und zum Strafgericht." },
      { number: 10, text: "Ihre Augen sollen erblinden, dass sie nichts mehr sehen, und ihr Rücken soll sich beugen unter der ständigen Last.\"*", footnotes: ["Psalm 69,23-24"] },
      { number: 11, text: "Nun frage ich: \"Sind sie etwa gestrauchelt, um nie wieder aufzustehen?\" Auf keinen Fall! Vielmehr hat ihr Fehltritt den anderen Völkern die Rettung gebracht, um die Juden wiederum eifersüchtig zu machen." },
      { number: 12, text: "Wenn nun schon die Welt durch ihren Fehltritt reich gemacht wurde und ihr Verlust für die anderen Völker einen großen Gewinn brachte, was wird es dann erst sein, wenn Israel in voller Zahl umkehrt?" },
      { number: 13, text: "Euch Nichtjuden aber sage ich: Als Apostel für die Völker bin ich froh über meinen Dienst." },
      { number: 14, text: "Denn vielleicht kann ich dadurch mein eigenes Volk eifersüchtig machen und einige von ihnen retten." },
      { number: 15, text: "Denn wenn schon die Verstoßung Israels der Welt die Versöhnung mit Gott brachte, was wird dann erst Israels Wiederannahme bringen? Nicht weniger als dass Tote lebendig werden." },
      { number: 16, text: "Wenn das erste Brot der neuen Ernte Gott geweiht ist, dann ist alles Korn dieser Ernte geheiligt. Wenn die Wurzel des Baumes Gott geweiht ist, dann sind es auch die Zweige." },
      { number: 17, text: "Nun sind einige Zweige ausgebrochen worden, und du wurdest als neuer Zweig unter die übrigen eingepfropft. Obwohl du von einem wilden Ölbaum stammst, hast du jetzt Anteil am Saft aus der Wurzel des edlen Ölbaums." },
      { number: 18, text: "Du hast keinen Grund, verächtlich auf die anderen Zweige herabzusehen. Und wenn du es dennoch tust, sollte dir klar sein: Nicht du trägst die Wurzel, sondern die Wurzel trägt dich!" },
      { number: 19, text: "Vielleicht wirst du nun sagen: \"Die Zweige sind ja herausgebrochen worden, damit ich eingepfropft werden konnte.\"" },
      { number: 20, text: "Das ist richtig. Aber dass sie ausgebrochen wurden, lag an ihrem Unglauben. Und du hast deinen Stand nur durch den Glauben. Sei also nicht überheblich, sondern pass auf, dass es dir nicht genauso geht." },
      { number: 21, text: "Denn wenn Gott die natürlichen Zweige nicht verschont hat, warum sollte er dann dich verschonen?" },
      { number: 22, text: "Du siehst hier also die Güte und die Strenge Gottes: Seine Strenge gilt denen, die sich von ihm abgewandt haben, aber seine Güte gilt dir, sofern du dich auf seine Güte verlässt; sonst wirst auch du herausgeschnitten werden." },
      { number: 23, text: "Doch auch die anderen Zweige können wieder eingepfropft werden, vorausgesetzt, sie halten nicht an ihrem Unglauben fest. Gott hat sehr wohl die Macht dazu." },
      { number: 24, text: "Denn wenn du aus dem wilden Ölbaum, zu dem du von Natur aus gehörtest, ausgeschnitten und gegen die natürliche Ordnung in den edlen Ölbaum eingepfropft wurdest, wie viel leichter wird es dann sein, die Zweige, die natürlicherweise zum edlen Ölbaum gehören, wieder an ihre Stelle einzupfropfen." },
      { number: 25, text: "Und damit ihr euch nichts auf eure Klugheit einbildet und falsche Schlüsse daraus zieht, will ich euch das folgende Geheimnis bekannt machen: Ein Teil von Israel hat sich verhärtet. Aber das gilt nur so lange, bis die volle Zahl von Menschen aus den anderen Völkern zum Glauben gekommen ist." },
      { number: 26, text: "Israel als Ganzes wird allerdings so gerettet werden, wie geschrieben steht: \"Aus Zion wird der Retter kommen, der alle Gottlosigkeit von Jakobs Nachkommen entfernt." },
      { number: 27, text: "Und der Bund, den ich mit ihnen schließen werde, besteht darin, dass ich sie von ihren Sünden befreie.\"*", footnotes: ["Jesaja 59,20-21; 27,9"] },
      { number: 28, text: "Ihre Einstellung zum Evangelium macht sie zwar zu Feinden – was euch zugutekommt –, aber von der Erwählung her gesehen sind sie Geliebte – wegen ihrer Stammväter." },
      { number: 29, text: "Denn Gott nimmt seine Gnadenerweise nicht zurück und bereut seine Berufungen nie." },
      { number: 30, text: "Früher hattet ihr Gott nicht gehorcht und habt jetzt doch – wegen Israels Ungehorsam – Gottes Erbarmen gefunden." },
      { number: 31, text: "So sind auch sie jetzt ungehorsam geworden, damit sie dadurch, dass ihr Gottes Erbarmen gefunden habt, schließlich ebenso Erbarmen finden." },
      { number: 32, text: "Denn Gott hat alle zusammen zu Gefangenen ihres Ungehorsams gemacht, weil er allen sein Erbarmen schenken will." },
      { number: 33, text: "Wie unermesslich reich ist Gottes Weisheit, / wie abgrundtief seine Erkenntnis! / Wie unergründlich sind seine Entscheidungen, / wie unerforschlich seine Wege!" },
      { number: 34, text: "Denn wer hat jemals die Gedanken des Herrn erkannt, / wer ist je sein Berater gewesen?" },
      { number: 35, text: "Wer hat ihm je etwas gegeben, / das Gott ihm zurückgeben müsste?" },
      { number: 36, text: "Denn von ihm kommt alles, / durch ihn steht alles / und zu ihm geht alles. / Ihm gebührt die Ehre für immer und ewig! Amen." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Weil Gott uns solches Erbarmen geschenkt hat, liebe Geschwister, ermahne ich euch nun auch, dass ihr euch mit Leib und Leben Gott als lebendiges und heiliges Opfer zur Verfügung stellt. An solchen Opfern hat er Freude und das ist der wahre Gottesdienst.", heading: "12-15: Gerechtigkeit im Alltag des Christen\nIn seiner Einstellung zum Nächsten (12)\nDie Gerechtigkeit im Alltag des Christen" },
      { number: 2, text: "Und richtet euch nicht nach den Maßstäben dieser Welt, sondern lasst die Art und Weise, wie ihr denkt, von Gott erneuern und euch dadurch umgestalten, sodass ihr prüfen könnt, ob etwas Gottes Wille ist – ob es gut ist, ob es Gott gefallen würde und ob es zum Ziel führt." },
      { number: 3, text: "Aufgrund der Gnade, die Gott mir gegeben hat, warne ich jeden Einzelnen von euch: Denkt nicht höher von euch, als es angemessen ist, und seid besonnen! Maßstab dafür ist der Glaube, von dem Gott jedem ein bestimmtes Maß zugeteilt hat." },
      { number: 4, text: "Es ist wie bei unserem Körper. Er bildet ein lebendiges Ganzes, hat aber viele Glieder, von denen jedes seine besondere Aufgabe hat." },
      { number: 5, text: "Genauso sind wir alle in Verbindung mit Christus ein einziger Leib und einzeln genommen Glieder, die voneinander abhängig sind." },
      { number: 6, text: "Wir haben ganz verschiedene Gaben, so wie Gott sie uns in seiner Gnade gegeben hat. Der eine hat die Gabe, Worte Gottes weiterzugeben. Er soll das in Übereinstimmung mit dem Glauben tun!" },
      { number: 7, text: "Ein anderer ist befähigt, praktische Aufgaben zu übernehmen. Er soll diese Gabe einsetzen! Wenn jemand die Gabe des Lehrens hat, soll er lehren!" },
      { number: 8, text: "Wenn jemand die Gabe der Seelsorge hat, dann soll er sie ausüben. Wer Bedürftige unterstützt, tue das uneigennützig! Wer Verantwortung übernimmt, muss fleißig sein! Wer sich um Notleidende kümmert, soll es mit fröhlichem Herzen tun!" },
      { number: 9, text: "Liebe muss echt sein, ohne Heuchelei! Verabscheut das Böse, haltet am Guten fest!" },
      { number: 10, text: "Seid einander in herzlicher geschwisterlicher Liebe zugetan! Übertrefft euch in gegenseitigem Respekt!" },
      { number: 11, text: "Werdet im Fleiß nicht nachlässig, lasst den Geist Gottes in euch brennen und dient so dem Herrn!" },
      { number: 12, text: "Freut euch, weil ihr Hoffnung habt, bleibt standhaft in Bedrängnis, seid treu im Gebet!" },
      { number: 13, text: "Nehmt Anteil an den Nöten der Gläubigen und helft ihnen! Bemüht euch um Gastfreundschaft!" },
      { number: 14, text: "Segnet eure Verfolger, wünscht ihnen Gutes und verflucht sie nicht!" },
      { number: 15, text: "Freut euch mit denen, die sich freuen; weint mit denen, die weinen!" },
      { number: 16, text: "Seid miteinander auf das gleiche Ziel bedacht! Strebt nicht hoch hinaus, sondern lasst euch auch von geringen Dingen in Anspruch nehmen! Haltet euch nicht selbst für klug!" },
      { number: 17, text: "Vergeltet niemand Böses mit Bösem! Bemüht euch um ein vorbildliches Verhalten gegenüber jedermann!" },
      { number: 18, text: "Soweit es irgend möglich ist, und soweit es auf euch ankommt, lebt mit allen Menschen in Frieden!" },
      { number: 19, text: "Rächt euch nicht selbst, ihr Lieben, sondern lasst Raum für den Zorn Gottes! Denn in der Schrift steht: \"Es ist meine Sache, das Unrecht zu rächen, sagt der Herr, ich werde Vergeltung üben!\"*", footnotes: ["5. Mose 32,35"] },
      { number: 20, text: "\"Wenn dein Feind hungrig ist, gib ihm zu essen, wenn er Durst hat, gib ihm zu trinken! Denn wenn du das tust, wirst du ihn zutiefst beschämen." },
      { number: 21, text: "Lass dich nicht vom Bösen besiegen, sondern besiege das Böse mit dem Guten!\"*", footnotes: ["Sprüche 25,21-22"] },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Jeder soll sich den Trägern der staatlichen Gewalt unterordnen. Denn alle staatliche Gewalt kommt von Gott, und jede Regierung ist von Gott eingesetzt.", heading: "In seinem Verhalten zum Staat (13)\nUmgang mit Behörden und anderen Menschen" },
      { number: 2, text: "Wer sich daher der staatlichen Gewalt widersetzt, stellt sich gegen die von Gott eingesetzte Ordnung und wird zu Recht bestraft werden." },
      { number: 3, text: "Denn wer Gutes tut, hat von den Regierenden nichts zu befürchten. Das hat nur der, der Böses tut. Wenn du also nicht in Furcht vor der Regierung leben willst, dann tue Gutes, und du wirst von ihr gelobt werden." },
      { number: 4, text: "Sie steht ja zu deinem Besten im Dienst Gottes. Tust du aber Böses, hast du allen Grund, sie zu fürchten, schließlich ist sie nicht umsonst die Trägerin von Polizei- und Strafgewalt. Auch darin ist sie Gottes Dienerin. Sie zieht den Schuldigen zur Verantwortung und vollstreckt damit Gottes Urteil an denen, die Böses tun." },
      { number: 5, text: "Es ist also notwendig, sich dem Staat unterzuordnen, nicht nur aus Angst vor Strafe, sondern auch wegen des Gewissens." },
      { number: 6, text: "Deshalb zahlt ihr ja auch Steuern, denn die Beamten sind Gottes Diener und haben sich berufsmäßig damit zu befassen." },
      { number: 7, text: "Gebt jedem das, was ihm zusteht: Steuer, dem die Steuer, Zoll, dem der Zoll, Respekt, dem Respekt, und Ehre, dem die Ehre gebührt." },
      { number: 8, text: "Abgesehen davon, dass ihr einander lieben sollt, bleibt keinem etwas schuldig! Wer den anderen liebt, hat das Gesetz erfüllt." },
      { number: 9, text: "Denn das Gesetz sagt: \"Du sollst die Ehe nicht brechen, du sollst niemand ermorden, du sollst nicht stehlen, du sollst der Begierde keinen Raum geben.\"* Diese und alle anderen Gebote sind in dem einen Satz zusammengefasst: \"Liebe deinen Nächsten wie dich selbst!\"*", footnotes: ["2. Mose 20,13-17", "3. Mose 19,18"] },
      { number: 10, text: "Die Liebe tut dem Nächsten nichts Böses an. Darum wird durch die Liebe das ganze Gesetz erfüllt." },
      { number: 11, text: "Achtet also auf die Gelegenheiten, die Gott euch gibt. Es ist höchste Zeit, aus dem Schlaf aufzuwachen, denn jetzt ist unsere Rettung noch näher als damals, als wir zum Glauben kamen." },
      { number: 12, text: "Die Nacht geht zu Ende, bald ist es Tag. Darum wollen wir uns von allem trennen, was man im Dunkeln tut, und die Waffen des Lichts ergreifen!" },
      { number: 13, text: "Lasst uns ein Leben führen, wie es zum hellen Tag passt, ein Leben ohne Fress- und Saufgelage, ohne Bettgeschichten und Sexorgien, ohne Streit und Rechthaberei." },
      { number: 14, text: "Zieht vielmehr den Herrn Jesus Christus an und trefft keine Vorkehrungen für die Begierden, die in euch sind!" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Nehmt den, der im Glauben schwach ist, vorbehaltlos an und streitet nicht über seine Ansichten mit ihm.", heading: "In seinem Umgang mit schwachen Christen (14-15)\nDie Schwachen und die Starken im Glauben" },
      { number: 2, text: "Einer glaubt zum Beispiel, er dürfe alles essen. Der Schwache jedoch ernährt sich rein vegetarisch." },
      { number: 3, text: "Wer alles isst, darf den nicht verachten, der nicht alles isst. Und wer nicht alles isst, darf den nicht verurteilen, der alles isst, denn Gott hat ihn genauso angenommen wie dich." },
      { number: 4, text: "Wie kommst du denn dazu, den Diener eines anderen zur Rechenschaft zu ziehen? Ob er mit seinem Tun bestehen kann oder nicht, geht nur seinen Herrn etwas an. Und er wird bestehen, denn sein Herr ist in der Lage, dafür zu sorgen." },
      { number: 5, text: "Der eine hebt bestimmte Tage hervor, für den anderen ist jeder Tag gleich. Aber jeder soll mit voller Überzeugung zu seiner Auffassung stehen." },
      { number: 6, text: "Wer einen bestimmten Tag bevorzugt, tut das zur Ehre des Herrn. Genauso ist es bei dem, der alles isst. Er tut es zur Ehre des Herrn, denn er dankt Gott dafür. Und auch der, der nicht alles isst, tut das zur Ehre des Herrn und sagt Gott Dank." },
      { number: 7, text: "Denn keiner von uns lebt für sich selbst und keiner von uns stirbt für sich selbst." },
      { number: 8, text: "Wenn wir leben, leben wir für den Herrn, und wenn wir sterben, gehören wir dem Herrn. Im Leben und im Tod gehören wir dem Herrn." },
      { number: 9, text: "Dazu ist Christus ja gestorben und wieder lebendig geworden, dass er über Tote und Lebende der Herr sei." },
      { number: 10, text: "Warum verurteilst du dann deinen Bruder? Und du, warum verachtest du ihn? Wir werden doch alle vor den Richterstuhl Gottes gestellt werden." },
      { number: 11, text: "Denn es heißt in der Schrift: \"So wahr ich lebe, sagt der Herr: Alle Knie werden sich vor mir beugen, und jede Zunge wird Gott anerkennen und preisen.\"*", footnotes: ["Jesaja 45,23"] },
      { number: 12, text: "Also wird jeder von uns für sich selbst vor Gott Rechenschaft abzulegen haben." },
      { number: 13, text: "Hören wir doch auf, uns gegenseitig zu verurteilen! Achten wir vielmehr darauf, dass wir unserem Bruder kein Hindernis in den Weg legen und ihn zu Fall bringen!" },
      { number: 14, text: "Ich weiß und bin durch den Herrn Jesus fest davon überzeugt, dass nichts von Natur aus unrein ist. Aber für den, der etwas als unrein ansieht, ist es auch unrein." },
      { number: 15, text: "Wenn du also deinen Bruder wegen einer Speise in innere Not bringst, dann lebst du nicht mehr in der Liebe. Bring ihn mit deinem Essen nicht ins Verderben! Christus ist doch auch für ihn gestorben." },
      { number: 16, text: "Lasst das Gute, das Gott euch geschenkt hat, nicht in Verruf kommen!" },
      { number: 17, text: "Denn im Reich Gottes geht es doch nicht um Essen und Trinken, sondern um das, was der Heilige Geist bewirkt: Gerechtigkeit, Frieden und Freude." },
      { number: 18, text: "Wer Christus auf diese Weise dient, wird von Gott anerkannt und von den Menschen geachtet." },
      { number: 19, text: "Lasst uns also nach dem streben, was zum Frieden und zum Aufbau der Gemeinde beiträgt!" },
      { number: 20, text: "Zerstöre nicht wegen einer Essensfrage das Werk Gottes! Gewiss, es ist alles rein, aber es ist verwerflich, einen anderen durch sein Essen zu Fall zu bringen." },
      { number: 21, text: "Deshalb isst du am besten kein Fleisch und trinkst keinen Wein und vermeidest überhaupt alles, was deinen Bruder zu Fall bringen könnte." },
      { number: 22, text: "Behandle deine Überzeugung als eine Sache zwischen dir und Gott! Wohl dem, der sich in seiner Überzeugung nicht anklagen muss!" },
      { number: 23, text: "Wer aber beim Essen ein schlechtes Gewissen hat, ist schon verurteilt, denn er handelt nicht aus der Überzeugung des Glaubens. Und alles, was nicht aus dem Glauben kommt, ist Sünde." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Wir, die Starken, haben die Pflicht, die Schwächen der Schwachen zu tragen, anstatt selbstgefällig nur an uns zu denken." },
      { number: 2, text: "Jeder von uns soll auf den anderen Rücksicht nehmen, damit es ihm gut geht und er gefördert wird." },
      { number: 3, text: "Auch der Messias hat nicht für sich selbst gelebt, sondern so, wie es in der Schrift heißt: \"Die Beschimpfungen von denen, die dich beschimpfen, haben mich getroffen.\"*", footnotes: ["Psalm 69,10"] },
      { number: 4, text: "Und alles, was in der Heiligen Schrift steht, wurde früher aufgeschrieben, damit wir daraus lernen. Die Schrift ermutigt uns zum Durchhalten, bis sich unsere Hoffnung erfüllt." },
      { number: 5, text: "Und der Gott, von dem Geduld und Ermutigung kommen, gebe euch die Einmütigkeit, wie sie Jesus Christus entspricht," },
      { number: 6, text: "damit ihr ihn, den Vater unseres Herrn Jesus Christus, einmütig wie aus einem Mund preist." },
      { number: 7, text: "Deshalb nehmt euch gegenseitig an, wie auch Christus euch angenommen hat, damit Gott geehrt wird!" },
      { number: 8, text: "Denn ich sage euch: der Messias ist ein Diener der Juden geworden, um die Wahrhaftigkeit Gottes zu bezeugen. Er wollte die Zusagen bestätigen, die er ihren Vätern gegeben hatte,", heading: "Paulus und die Christen in Rom\nDer Auftrag des Völkerapostels" },
      { number: 9, text: "und wollte, dass die Nichtjuden Gott für seine Barmherzigkeit ehren, wie auch geschrieben steht: \"Darum will ich dich preisen unter den Völkern. Zum Ruhm deines Namens will ich Loblieder singen.\"*", footnotes: ["Psalm 18,50"] },
      { number: 10, text: "An anderer Stelle heißt es: \"Freut euch mit seinem Volk, ihr Völker alle!\"*", footnotes: ["5. Mose 32,43"] },
      { number: 11, text: "Und weiter: \"Lobt den Herrn, all ihr Völker, alle Nationen sollen ihn preisen!\"*", footnotes: ["Psalm 117,1"] },
      { number: 12, text: "Und Jesaja sagt: \"Es kommt der Spross, der aus der Wurzel Isais hervorwächst. Er steht auf, um über die Völker zu herrschen. Auf ihn werden die Völker hoffen.\"*", footnotes: ["Jesaja 11,10 nach der LXX zitiert."] },
      { number: 13, text: "Möge Gott, die Quelle der Hoffnung, euch im Glauben mit Freude und Frieden erfüllen, damit eure Hoffnung durch die Kraft des Heiligen Geistes immer stärker wird." },
      { number: 14, text: "Ich bin aber persönlich davon überzeugt, liebe Geschwister, dass ihr selbst in der Lage seid zu tun, was gut und richtig ist. Es mangelt euch an keiner Erkenntnis, und ihr seid auch fähig, euch gegenseitig zu ermahnen." },
      { number: 15, text: "Ich habe euch teilweise recht offen geschrieben, weil ich euch einiges in Erinnerung rufen wollte. Gott hat mich in seiner Gnade ja berufen," },
      { number: 16, text: "ein Diener von Jesus Christus unter den nichtjüdischen Völkern zu sein. Wie ein Priester im Dienst der guten Nachricht Gottes arbeite ich darauf hin, dass sie eine Opfergabe werden, an der Gott Freude hat, weil sie durch den Heiligen Geist geheiligt ist." },
      { number: 17, text: "Dass ich vor Gott darauf stolz sein kann, habe ich allein Jesus Christus zu verdanken." },
      { number: 18, text: "Denn ich würde niemals wagen, von etwas zu reden, was nicht Christus durch mich gewirkt hätte: Menschen aus nichtjüdischen Völkern wurden Gott gehorsam, und zwar durch sein Wort und Werk," },
      { number: 19, text: "in der Kraft von Zeichen und Wundern und in der Kraft des Heiligen Geistes. So habe ich von Jerusalem aus in der ganzen Gegend die Botschaft des Messias bekannt gemacht – bis an die Grenze von Illyrien*.", footnotes: ["Illyrien. Römische Provinz nördlich von Mazedonien (heute Albanien)."] },
      { number: 20, text: "Ich habe darauf geachtet, diese gute Botschaft nicht dort zu verkündigen, wo er schon bekannt war, um nicht auf einem fremden Fundament zu bauen." },
      { number: 21, text: "Ich hielt mich an das, was geschrieben steht: \"Gerade die, denen noch nicht von ihm gesagt wurde, sollen ihn kennenlernen, gerade die, die noch nicht von ihm gehört haben, sollen verstehen.\"*", footnotes: ["Jesaja 52,15"] },
      { number: 22, text: "Das ist es auch, was mich immer wieder gehindert hat, zu euch zu kommen,", heading: "Reisepläne des Apostels" },
      { number: 23, text: "obwohl ich mich seit vielen Jahren danach sehne, euch zu sehen. Aber jetzt habe ich in diesen Gegenden kein neues Arbeitsfeld mehr" },
      { number: 24, text: "und plane, nach Spanien zu reisen. Auf dem Weg dorthin hoffe ich, euch zu besuchen und dann mit eurer Unterstützung die Reise fortzusetzen. Doch vorher möchte ich mich einige Zeit an der Gemeinschaft mit euch erfreuen." },
      { number: 25, text: "Jetzt reise ich aber erst einmal nach Jerusalem, um den Gläubigen dort Hilfe zu bringen." },
      { number: 26, text: "Denn die Gemeinden in Mazedonien* und Achaja* haben beschlossen, etwas für die Armen unter den Gläubigen in Jerusalem zusammenzulegen.", footnotes: ["Mazedonien. Römische Provinz auf der Balkanhalbinsel. Sie umfasste den nördlichen Teil des heutigen Griechenland.", "Achaja. Römische Provinz, die den südlichen Teil Griechenlands umfasste"] },
      { number: 27, text: "Sie haben das gern getan und stehen ja auch in ihrer Schuld. Denn wenn die Völker Anteil an den geistlichen Gütern der Jerusalemer Gläubigen bekommen haben, sind sie auch verpflichtet, ihnen mit irdischen Gütern zu dienen." },
      { number: 28, text: "Aber wenn ich diese Sache zum Abschluss gebracht und ihnen den Ertrag der Sammlung versiegelt übergeben habe, will ich auf dem Weg nach Spanien bei euch vorbeikommen." },
      { number: 29, text: "Und ich weiß, dass ich euch die ganze Fülle des Segens von Christus mitbringen werde." },
      { number: 30, text: "Ich bitte euch dringend, liebe Geschwister: Helft mir zu kämpfen, und betet für mich zu Gott. Denn durch unseren Herrn Jesus Christus und durch die Liebe, die der Geist wirkt, sind wir doch miteinander verbunden." },
      { number: 31, text: "Betet, dass ich vor den Gefahren geschützt bin, die mir von den Ungläubigen in Judäa drohen, und dass meine Hilfe für Jerusalem von den Gläubigen dort gut aufgenommen wird!" },
      { number: 32, text: "Dann kann ich, wenn es Gottes Wille ist, mit Freude zu euch kommen und mich bei euch etwas erholen." },
      { number: 33, text: "Der Gott des Friedens sei mit euch allen! Amen." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Ich empfehle euch ausdrücklich unsere Schwester Phöbe, Mitarbeiterin in der Gemeinde in Kenchreä*.", heading: "Empfehlungen und viele Grüße", footnotes: ["Kenchreä. Der östliche Hafen von Korinth am Sarinischen Golf, etwa 7 km von der Stadt entfernt."] },
      { number: 2, text: "Nehmt sie im Namen des Herrn auf, wie es Heilige tun sollen, und steht ihr in jeder Sache bei, in der sie euch braucht. Auch sie ist vielen – nicht zuletzt mir selbst – eine große Stütze gewesen." },
      { number: 3, text: "Grüßt Priska und ihren Mann Aquila, meine Mitarbeiter im Dienst für Jesus Christus." },
      { number: 4, text: "Für mein Leben haben sie ihren Kopf hingehalten. Nicht nur ich habe ihnen dafür zu danken, sondern auch alle nichtjüdischen Gemeinden." },
      { number: 5, text: "Grüßt auch die Gemeinde, die in ihrem Haus zusammenkommt. Grüßt meinen lieben Epänetus. Er war der erste in der Provinz Asia*, der zum Glauben an Christus kam.", footnotes: ["Asia. Römische Provinz im westlichen Teil Kleinasiens."] },
      { number: 6, text: "Grüßt Maria, die so viel für euch gearbeitet hat." },
      { number: 7, text: "Grüßt Andronikus und Junias, meine Landsleute, die schon vor mir an Christus geglaubt haben. Sie waren auch mit mir im Gefängnis und sind unter den Aposteln sehr angesehen." },
      { number: 8, text: "Grüßt meinen lieben Ampliatus, mit dem ich durch den Herrn verbunden bin." },
      { number: 9, text: "Grüßt Urbanus, unseren Mitarbeiter im Dienst für Christus, und meinen lieben Stachys." },
      { number: 10, text: "Grüßt Apelles, der sich im Glauben an Christus bewährt hat. Grüßt die im Haus des Aristobul." },
      { number: 11, text: "Grüßt meinen Landsmann Herodion. Grüßt die, die zum Haus des Narzissus gehören und an den Herrn glauben." },
      { number: 12, text: "Grüßt Tryphäna und Tryphosa, die sich für den Herrn mühen, und die liebe Persis, die so unermüdlich für den Herrn gearbeitet hat." },
      { number: 13, text: "Grüßt Rufus, den der Herr erwählt hat, und seine Mutter, die auch mir eine Mutter gewesen ist." },
      { number: 14, text: "Grüßt Asynkritus, Phlegon, Hermes, Patrobas, Hermas und die anderen Geschwister bei ihnen." },
      { number: 15, text: "Grüßt Philologus und Julia, Nereus und seine Schwester, auch Olympas und alle Gläubigen bei ihnen." },
      { number: 16, text: "Grüßt einander mit einem heiligen Kuss.* Alle Gemeinden, die zu Christus gehören, grüßen euch.", footnotes: ["Kuss. Der Begrüßungskuss auf Stirn oder Wange war unter Familienangehörigen und Freunden üblich. Unter Gläubigen drückte ein keuscher Kuss die geistliche Verwandtschaft aus."] },
      { number: 17, text: "Ich bitte euch, Brüder, nehmt euch vor denen in acht, die von der Lehre abweichen, wie ihr sie gelernt habt! Sie rufen nur Spaltungen hervor und bringen den Glauben der Geschwister in Gefahr. Geht ihnen aus dem Weg!" },
      { number: 18, text: "Solche Menschen dienen nicht Christus, unserem Herrn, sondern dem eigenen Bauch*. Mit eindrucksvollen Reden und schmeichlerischen Worten führen sie arglose Menschen in die Irre.", footnotes: ["Bauch. Gemeint sind: Wohlergehen, Interessen, Begierden."] },
      { number: 19, text: "Über euch aber kann ich mich nur freuen, denn jeder weiß, dass ihr dem Wort Gottes gehorsam seid. Doch ich möchte euch auch weise zum Guten und unbeeinflusst vom Bösen wissen." },
      { number: 20, text: "Es wird nicht lange dauern, bis der Gott des Friedens den Satan unter euren Füßen zermalmt hat. Die Gnade unseres Herrn Jesus Christus sei mit euch!" },
      { number: 21, text: "Mein Mitarbeiter Timotheus lässt euch grüßen und ebenso meine Landsleute Luzius, Jason und Sosipater." },
      { number: 22, text: "Auch ich, Tertius, dem Paulus diesen Brief diktiert hat, grüße euch, verbunden durch den Herrn." },
      { number: 23, text: "Mein Gastgeber Gajus, in dessen Haus die ganze Gemeinde zusammenkommt, lässt euch ebenfalls grüßen. Auch der Stadtkämmerer Erastus und der Bruder Quartus lassen euch grüßen.(" },
      { number: 24, text: ")*", footnotes: ["Spätere Handschriften fügen hier oder nach V. 27 ein: Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen."] },
      { number: 25, text: "Dem Gott, der die Macht hat, euch durch das Evangelium, das mir anvertraut ist, und durch die Predigt von Jesus Christus im Glauben zu festigen; dem Gott, der uns das Geheimnis offenbart hat, das seit undenklichen Zeiten verborgen war;" },
      { number: 26, text: "dem ewigen Gott, der befohlen hat, diese Botschaft jetzt durch prophetische Schriften allen Völkern bekannt zu machen, damit sie ihr glauben und gehorchen;" },
      { number: 27, text: "dem allein weisen Gott, den wir durch Jesus Christus preisen, gebührt alle Ehre in alle Ewigkeit! Amen." },
    ] },
  ],
};